      "rank": 2,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Christophe Salomon",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provide a clean, tunable setting for universal many-body physics and the connection between superfluid regimes.",
        "attribution": "Salomon and Grimm led important, independent experimental programs that established and explored ultracold Fermi gases; Ketterle is already a laureate.",
        "maturity": "The field has produced sustained, reproducible results across laboratories and regimes.",
        "uncertainties": [
          "The discovery and its experimental development are broad, so the fairest boundaries of the contribution are not obvious."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice experiments made controlled quantum simulation of interacting many-body systems possible and revealed phases and dynamics inaccessible to simple perturbative treatment.",
        "attribution": "Bloch and Greiner were central experimental leaders in establishing this approach; the theoretical foundations also involved Cirac and Zoller.",
        "maturity": "The methods have been replicated widely and have developed into a substantial program of precision many-body experiments.",
        "uncertainties": [
          "The breadth of quantum simulation makes it difficult to define a single prize-sized discovery and a complete credit boundary."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computation joined a scalable information-processing proposal to precise control of individual quantum systems, with lasting influence on quantum physics.",
        "attribution": "Cirac helped formulate the influential ion-trap gate proposal, while Blatt's experiments demonstrated and advanced controlled ion operations.",
        "maturity": "Ion-trap control is exceptionally well established, though large-scale fault-tolerant computation remains an ongoing goal.",
        "uncertainties": [
          "The proposed prize might recognize a mature physical control method or a still-developing computing architecture."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information can in principle be protected, changing the foundations and prospects of quantum information physics.",
        "attribution": "Kitaev, Steane, and Shor each made distinct foundational contributions to fault-tolerant quantum information and error correction.",
        "maturity": "The theory is firmly established, and experimental demonstrations have advanced, although scalable fault tolerance is not yet routine.",
        "uncertainties": [
          "The connection between a major theoretical framework and experimentally mature physics is still evolving."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays give unprecedented control over interacting quantum spins and enable direct studies of many-body dynamics.",
        "attribution": "Browaeys, Saffman, and Lukin made important experimental and conceptual contributions to controllable Rydberg-atom systems.",
        "maturity": "The platform is reproducible and rapidly expanding, but many of its most ambitious scientific results are recent.",
        "uncertainties": [
          "It may be too early to separate enduring fundamental discoveries from the promise of a powerful platform."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion brought massive, measurable objects into regimes where quantum behavior can be prepared and studied, bearing directly on the quantum-to-classical boundary.",
        "attribution": "Teufel and Aspelmeyer led key experimental advances in controlling and cooling mechanical systems; the listed work spans several devices and groups.",
        "maturity": "Ground-state cooling and quantum control have been reproduced in multiple platforms, while stronger tests of macroscopic quantum behavior continue.",
        "uncertainties": [
          "The field has several complementary platforms and no single experiment yet settles how far quantum behavior extends to large objects."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Giovanni Modugno",
        "Massimo Inguscio"
      ],
      "assessment": {
        "nobel_worthiness": "Observing Anderson localization with matter waves connected a central idea in disordered quantum systems to direct, controllable atomic experiments.",
        "attribution": "Modugno and Inguscio are credible experimental contributors; Aspect's earlier theoretical role is significant, though he is already a laureate.",
        "maturity": "Matter-wave localization has been explored in several settings and has a strong experimental foundation.",
        "uncertainties": [
          "The specific discovery boundary and division of credit among the listed names are unclear."
        ]
      }
    }
  ]
